def _build_graph(adj):
    if not adj: return None
    nodes = {i+1: Node(i+1) for i in range(len(adj))}
    for i, neighbors in enumerate(adj):
        nodes[i+1].neighbors = [nodes[n] for n in neighbors]
    return nodes[1]
def _graph_adj(node):
    if not node: return []
    visited = {}
    def dfs(n):
        if n.val in visited: return
        visited[n.val] = n
        for nb in n.neighbors: dfs(nb)
    dfs(node)
    n = len(visited)
    return [[nb.val for nb in visited[i+1].neighbors] for i in range(n)]
